#!/bin/sh
# Generated by Claude Code 2.1.263 (claude-opus-5[1m])
#
# Build gl4es as a static library for arm64-v8a.
#
# gl4es translates the fixed-function OpenGL 1.x calls that Neverball's
# renderer makes into OpenGL ES 2.0, the same way the web build does.
# NOEGL and NOX11 mean gl4es never creates a context of its own; we make
# the EGL context and hand OpenXR the same one.
#
# gl4es declares cmake_minimum_required(VERSION 2.8.12), which modern
# CMake rejects outright, so use the SDK's 3.22.1.

set -e

DEPS_DIR=$(cd "$(dirname "$0")" && pwd)
SRC="$DEPS_DIR/src/gl4es"
BUILD="$DEPS_DIR/build/gl4es-arm64-v8a"

: "${ANDROID_SDK_ROOT:=$HOME/Android/Sdk}"
: "${ANDROID_NDK_ROOT:=$ANDROID_SDK_ROOT/ndk/27.2.12479018}"

CMAKE="$ANDROID_SDK_ROOT/cmake/3.22.1/bin/cmake"
NINJA="$ANDROID_SDK_ROOT/cmake/3.22.1/bin/ninja"

[ -d "$SRC" ] || { echo "gl4es sources missing; run fetch-deps.sh" >&2; exit 1; }

"$CMAKE" -S "$SRC" -B "$BUILD" -G Ninja \
    -DCMAKE_MAKE_PROGRAM="$NINJA" \
    -DCMAKE_TOOLCHAIN_FILE="$ANDROID_NDK_ROOT/build/cmake/android.toolchain.cmake" \
    -DANDROID_ABI=arm64-v8a \
    -DANDROID_PLATFORM=android-29 \
    -DCMAKE_BUILD_TYPE=Release \
    -DNOX11=ON \
    -DNOEGL=ON \
    -DSTATICLIB=ON \
    -DNO_LOADER=ON \
    -DNO_INIT_CONSTRUCTOR=ON \
    -DUSE_ANDROID_LOG=ON \
    -DDEFAULT_ES=2

"$CMAKE" --build "$BUILD" -j "$(nproc)"

echo "gl4es: $SRC/lib/libGL.a"
